# ---------- CSS ----------
(".foot{position:fixed;",
 ".enso{margin:0 0 4px;padding:10px 16px 8px;background:#fff;border-bottom:1px solid var(--panel-border)}\n.enso .row1{display:flex;align-items:center;gap:10px;margin-bottom:4px}\n.enso .badge{font-weight:700;font-size:12px;padding:2px 9px;border-radius:3px;color:#fff;background:var(--coral)}\n.enso .badge.nina{background:var(--blue)}.enso .badge.neu{background:var(--text-light)}\n.enso .v{font-weight:700;color:var(--text)}\n.enso small{color:var(--text-light);font-size:11px}\n.enso canvas{width:100%;height:54px;display:block;margin-top:4px}\n.cmp{margin:6px 0 4px}\n.cmpDiv{position:absolute;top:0;bottom:0;width:0;border-left:2px solid #fff;box-shadow:0 0 0 1px rgba(0,0,0,.4);z-index:460;pointer-events:none}\n.cmpDiv::after{content:'◀ ▶';position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);background:#fff;color:#333;font-size:10px;padding:3px 6px;border-radius:12px;box-shadow:0 1px 4px rgba(0,0,0,.3)}\n.cmpLbl{position:absolute;top:8px;background:rgba(255,255,255,.9);padding:2px 8px;font-size:11px;font-weight:600;color:var(--text);z-index:461;pointer-events:none}\n.regionBox{position:absolute;border:2px dashed var(--blue);background:rgba(44,133,215,.12);pointer-events:none;z-index:470}\n.rgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:8px 14px;flex:1 1 auto;min-height:0}\n.rgrid .mini{display:flex;flex-direction:column;min-height:0}\n.rgrid .mini span{font-size:11px;font-weight:600;color:var(--text-light)}\n.rgrid canvas{flex:1 1 auto;min-height:0}\n.tools button.on{background:var(--blue);color:#fff}\n.kbd{display:inline-block;border:1px solid var(--panel-border);border-radius:3px;padding:0 5px;font-size:10px;background:#fff}\n.foot{position:fixed;"),
