('  <div class="opt" data-base="none">\n    <div class="hd"><input type="radio" name="base" value="none"><span class="lbl">None</span></div>\n  </div>',
 '  <div class="opt" data-base="co">\n    <div class="hd"><input type="radio" name="base" value="co"><span class="lbl">AIRS CO (500 hPa)<small>monthly</small></span><svg class="chev" viewBox="0 0 18 18"><path d="M4 7l5 5 5-5" fill="none" stroke="currentColor" stroke-width="1.8"/></svg></div>\n    <div class="body">\n      <div class="seg" id="coMode"><button data-m="abs" class="on">Concentration</button><button data-m="anom">Anomaly</button></div>\n      <div class="slider"><input type="range" id="coSl" min="0" max="0" value="0"><div class="lab"><span>Month</span><b id="coDate"></b></div></div>\n      <div class="legend"><div class="bar" id="coBar"></div><div class="lab2" id="coLab"></div></div>\n      <p class="note" id="coNote"></p>\n    </div>\n  </div>\n  <div class="opt" data-base="firem">\n    <div class="hd"><input type="radio" name="base" value="firem"><span class="lbl">Fire activity<small>monthly</small></span><svg class="chev" viewBox="0 0 18 18"><path d="M4 7l5 5 5-5" fill="none" stroke="currentColor" stroke-width="1.8"/></svg></div>\n    <div class="body">\n      <div class="seg" id="fmMode"><button data-m="abs" class="on">Detections</button><button data-m="anom">Anomaly</button></div>\n      <div class="slider"><input type="range" id="fmSl" min="0" max="0" value="0"><div class="lab"><span>Month</span><b id="fmDate"></b></div></div>\n      <div class="legend"><div class="bar" id="fmBar"></div><div class="lab2" id="fmLab"></div></div>\n      <p class="note" id="fmNote"></p>\n    </div>\n  </div>\n  <div class="opt" data-base="none">\n    <div class="hd"><input type="radio" name="base" value="none"><span class="lbl">None</span></div>\n  </div>\n  <div class="opt">\n    <div class="hd"><input type="checkbox" id="ckSync" checked><span class="lbl">Keep dates in sync<small>across basemaps</small></span></div>\n  </div>\n  <div class="opt" id="cmpOpt">\n    <div class="hd"><input type="checkbox" id="ckCmp"><span class="lbl">Compare two dates<small>swipe</small></span><svg class="chev" viewBox="0 0 18 18"><path d="M4 7l5 5 5-5" fill="none" stroke="currentColor" stroke-width="1.8"/></svg></div>\n    <div class="body"><div class="slider cmp"><input type="range" id="cmpSl" min="0" max="0" value="0"><div class="lab"><span>Right-hand date</span><b id="cmpDate"></b></div></div><p class="note">Drag the divider on the map. Left shows the main slider’s date, right shows this one.</p></div>\n  </div>'),
