# ---------- VARS: growth scales ----------
("const VARS={co2:{label:'CO₂',unit:'ppm',dp:2,raw:[0,12],detr:[-3,3]},ch4:{label:'CH₄',unit:'ppb',dp:1,raw:[0,60],detr:[-30,30]},pm25:{label:'PM₂.₅',unit:'µg/m³',dp:1,raw:[-20,20],detr:[-20,20],div:true}};",
 "const VARS={co2:{label:'CO₂',unit:'ppm',dp:2,raw:[0,12],detr:[-3,3],yoy:[0,6]},ch4:{label:'CH₄',unit:'ppb',dp:1,raw:[0,60],detr:[-30,30],yoy:[0,30]},pm25:{label:'PM₂.₅',unit:'µg/m³',dp:1,raw:[-20,20],detr:[-20,20],yoy:[-20,20],div:true}};"),
("const d=cur(s); if(!d) return null; const V=VARS[sel[s.net]]; const val=anomMode==='raw'?d.anom:d.detr; if(val==null) return '#9aa5b8';\n  if(V.div||anomMode==='detr'){const [a,b]=V.detr;return ramp((val-a)/(b-a),DIV);} const [a,b]=V.raw;return ramp((val-a)/(b-a),SEQ);",
 "const d=cur(s); if(!d) return null; const V=VARS[sel[s.net]]; const val=anomMode==='raw'?d.anom:anomMode==='detr'?d.detr:d.yoy; if(val==null) return '#9aa5b8';\n  if(V.div||anomMode==='detr'){const [a,b]=V.detr;return ramp((val-a)/(b-a),DIV);} const [a,b]=anomMode==='yoy'?V.yoy:V.raw;return ramp((val-a)/(b-a),SEQ);"),
("function popup(s){const d=cur(s),V=VARS[sel[s.net]];const [y,m,v]=d.latest;const a=anomMode==='raw'?d.anom:d.detr;","function popup(s){const d=cur(s),V=VARS[sel[s.net]];const [y,m,v]=d.latest;const a=anomMode==='raw'?d.anom:anomMode==='detr'?d.detr:d.yoy;"),
("  const seq=anomMode==='raw'; const used={}; for(const net in NETS) if(document.querySelector(`.netCk[data-net=${net}]`).checked) used[sel[net]]=1;\n  document.getElementById('stLegends').innerHTML=Object.keys(used).map(k=>{const V=VARS[k];const div=V.div||!seq;const [a,b]=div?V.detr:V.raw;",
 "  const seq=anomMode!=='detr'; const used={}; for(const net in NETS) if(document.querySelector(`.netCk[data-net=${net}]`).checked) used[sel[net]]=1;\n  document.getElementById('stLegends').innerHTML=Object.keys(used).map(k=>{const V=VARS[k];const div=V.div||!seq;const [a,b]=div?V.detr:(anomMode==='yoy'?V.yoy:V.raw);"),
("document.getElementById('anomNote').textContent=seq?'Latest month minus the mean of the same month over the previous 5 years. For CO₂ and CH₄ this is almost always positive because of the background growth; switch to trend-adjusted to see which sites are above or below their expected growth. PM₂.₅ has no strong trend, so its scale is diverging in both modes.':'Latest month minus the value expected from the previous 5 years’ linear trend for that calendar month. Red = above trend, blue = below.';",
 "document.getElementById('anomNote').textContent=anomMode==='raw'?'Latest month minus the mean of the same month over the previous 5 years. For CO₂ and CH₄ this is almost always positive because of the background growth; switch to trend-adjusted to see which sites are above or below their expected growth. PM₂.₅ has no strong trend, so its scale is diverging in both modes.':anomMode==='detr'?'Latest month minus the value expected from the previous 5 years’ linear trend for that calendar month. Red = above trend, blue = below.':'12-month growth: latest month minus the same month one year earlier. The classic El Niño signature is a CO₂ growth rate well above the ~2.5 ppm/yr background in the months after the SST peak.';"),
# ---------- basemap date lists, co/firem rendering, sync, compare ----------
("let baseLayer=null, baseMode='ndvi', pmMode='abs';",
 "let baseLayer=null, cmpLayer=null, baseMode='ndvi', pmMode='abs', coMode='abs', fmMode='abs';\nconst coSl=document.getElementById('coSl'); coSl.max=CO.months.length-1; coSl.value=CO.months.length-1;\nconst fmSl=document.getElementById('fmSl'); fmSl.max=FIREM.months.length-1; fmSl.value=FIREM.months.length-1;\nconst COSEQ=[[255,253,218],[254,196,79],[217,95,14],[140,20,60],[47,5,74]], FMSEQ=[[255,245,204],[254,178,76],[240,59,32],[128,0,38]];\nfunction decode8(b64){const bin=atob(b64);const a=new Int8Array(bin.length);for(let i=0;i<bin.length;i++)a[i]=(bin.charCodeAt(i)<<24)>>24;return a;}\nfunction decodeU8(b64){const bin=atob(b64);const a=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)a[i]=bin.charCodeAt(i);return a;}\nconst SL={oco2:{el:'ocoSl',dates:OCO.cycles.map(c=>c.end)},ndvi:{el:'ndviSl',dates:NDVI.map(c=>c.date+'-15')},s3:{el:'s3Sl',dates:S3N.map(c=>c.date)},pm:{el:'pmSl',dates:PM.months.map(c=>c.date+'-15')},co:{el:'coSl',dates:CO.months.map(c=>c.date+'-15')},firem:{el:'fmSl',dates:FIREM.months.map(c=>c.date+'-15')}};\nfunction nearestIdx(dates,d){const tt=Date.parse(d);let bi=0,bd=1e18;dates.forEach((x,i)=>{const dd=Math.abs(Date.parse(x)-tt);if(dd<bd){bd=dd;bi=i;}});return bi;}\nfunction curDate(mode){const s=SL[mode];return s?s.dates[+document.getElementById(s.el).value]:null;}\nfunction syncDates(from){if(!document.getElementById('ckSync').checked)return;const d=curDate(from);if(!d)return;for(const k in SL){if(k===from)continue;document.getElementById(SL[k].el).value=nearestIdx(SL[k].dates,d);}}\nfunction layerFor(mode,idx,forCmp){\n  if(mode==='oco2'){const c=OCO.cycles[idx];return L.imageOverlay(gridImage('oco'+idx,OCO.nx,OCO.ny,decode16(c.b64),v=>[ramp((v-OCO_LO)/(OCO_HI-OCO_LO),VIR),215]),[[-90,-180],[90,180]],{pane:forCmp?'basemapB':'basemap',opacity:.9,interactive:false});}\n  if(mode==='ndvi'){return L.imageOverlay(NDVI[idx].src,[[-90,-180],[90,180]],{pane:forCmp?'basemapB':'basemap',opacity:.95,interactive:false});}\n  if(mode==='s3'){return L.imageOverlay(S3N[idx].src,[[-60,-180],[80,180]],{pane:forCmp?'basemapB':'basemap',opacity:.95,interactive:false});}\n  if(mode==='pm'){const c=PM.months[idx],abs=pmMode==='abs';return L.imageOverlay(gridImage('pm'+idx+pmMode,PM.nx,PM.ny,decode16(abs?c.abs:c.anom),v=>abs?[ramp(v/60,PMSEQ),Math.round(Math.min(1,v/8)*205)]:[ramp((v+15)/30,DIV),Math.round(Math.min(1,Math.abs(v)/2.5)*215)]),[[-91,-181],[91,179]],{pane:forCmp?'basemapB':'basemap',opacity:.9,interactive:false});}\n  if(mode==='co'){const c=CO.months[idx],abs=coMode==='abs';const arr=abs?decodeU8(c.abs):decode8(c.anom);const a16=new Int16Array(arr.length);for(let k=0;k<arr.length;k++)a16[k]=(abs?arr[k]===0:arr[k]===-128)?-32768:arr[k]*10;return L.imageOverlay(gridImage('co'+idx+coMode,CO.nx,CO.ny,a16,v=>abs?[ramp((v-60)/140,COSEQ),205]:[ramp((v+30)/60,DIV),Math.round(Math.min(1,Math.abs(v)/4)*215)]),[[-90,-180],[90,180]],{pane:forCmp?'basemapB':'basemap',opacity:.9,interactive:false});}\n  if(mode==='firem'){const c=FIREM.months[idx],abs=fmMode==='abs';return L.imageOverlay(gridImage('fm'+idx+fmMode,FIREM.nx,FIREM.ny,decode16(abs?c.abs:c.anom),v=>abs?[ramp(Math.log10(1+v)/2.5,FMSEQ),Math.round(Math.min(1,v/3)*215)]:[ramp((v+100)/200,DIV),Math.round(Math.min(1,Math.abs(v)/10)*215)]),[[-90,-180],[90,180]],{pane:forCmp?'basemapB':'basemap',opacity:.9,interactive:false});}\n  return null;}\nmap.createPane('basemapB').style.zIndex=355;\nconst cmpDiv=document.createElement('div');cmpDiv.className='cmpDiv';cmpDiv.style.display='none';document.getElementById('map').appendChild(cmpDiv);\nconst cmpL1=document.createElement('div');cmpL1.className='cmpLbl';cmpL1.style.display='none';document.getElementById('map').appendChild(cmpL1);\nconst cmpL2=document.createElement('div');cmpL2.className='cmpLbl';cmpL2.style.display='none';document.getElementById('map').appendChild(cmpL2);\nlet cmpFrac=0.5;\nfunction applyClip(){if(!cmpLayer)return;const el=cmpLayer.getElement();if(!el)return;const mapEl=document.getElementById('map'),W=mapEl.clientWidth,x=W*cmpFrac;const r=el.getBoundingClientRect(),mr=mapEl.getBoundingClientRect();const leftPx=Math.max(0,x-(r.left-mr.left));el.style.clipPath=`inset(0 0 0 ${leftPx}px)`;cmpDiv.style.left=x+'px';cmpDiv.style.display='';cmpL1.style.display='';cmpL2.style.display='';cmpL1.style.right=(W-x+8)+'px';cmpL1.style.left='';cmpL2.style.left=(x+8)+'px';}\nmap.on('move zoom viewreset resize',()=>{if(cmpLayer)applyClip();});\n(function(){let drag=false;const mapEl=document.getElementById('map');mapEl.addEventListener('pointerdown',e=>{if(!cmpLayer)return;const x=e.clientX-mapEl.getBoundingClientRect().left;if(Math.abs(x-mapEl.clientWidth*cmpFrac)<14){drag=true;map.dragging.disable();e.preventDefault();}});window.addEventListener('pointermove',e=>{if(!drag)return;const mr=mapEl.getBoundingClientRect();cmpFrac=Math.max(0.02,Math.min(0.98,(e.clientX-mr.left)/mapEl.clientWidth));applyClip();});window.addEventListener('pointerup',()=>{if(drag){drag=false;map.dragging.enable();}});})();\nfunction showCmp(){if(cmpLayer){map.removeLayer(cmpLayer);cmpLayer=null;}cmpDiv.style.display='none';cmpL1.style.display='none';cmpL2.style.display='none';\n  const on=document.getElementById('ckCmp').checked&&SL[baseMode];document.getElementById('cmpOpt').classList.toggle('open',!!on);if(!on)return;\n  const cs=document.getElementById('cmpSl'),s=SL[baseMode];cs.max=s.dates.length-1;if(cs.dataset.mode!==baseMode){cs.value=Math.max(0,s.dates.length-1-(baseMode==='s3'?9:baseMode==='oco2'?6:6));cs.dataset.mode=baseMode;}\n  const i=+cs.value;cmpLayer=layerFor(baseMode,i,true);if(!cmpLayer)return;cmpLayer.addTo(map);cmpLayer.on('load',applyClip);document.getElementById('cmpDate').textContent=s.dates[i];cmpL1.textContent=curDate(baseMode);cmpL2.textContent=s.dates[i];setTimeout(applyClip,50);}\ndocument.getElementById('ckCmp').addEventListener('change',showCmp);document.getElementById('cmpSl').addEventListener('input',showCmp);"),
# showBase: generic rendering + co/firem notes + sync + cmp
("function showBase(){\n  if(baseLayer){map.removeLayer(baseLayer);baseLayer=null;}",
 "function showBase(from){\n  if(from)syncDates(from);\n  if(baseLayer){map.removeLayer(baseLayer);baseLayer=null;}"),
("    document.getElementById('pmNote').textContent=`Monthly mean surface PM₂.₅ (RH 35 %) from the NASA GEOS-CF v2 analysis on a 2° grid${abs?'':'; anomaly = this month minus the 2021–2025 same-month mean from GEOS-CF v1 (a version offset of roughly −0.8 µg/m³ is included)'}. Global mean ${c.mean.toFixed(1)} µg/m³${abs?'':`, mean anomaly ${c.manom>=0?'+':''}${c.manom.toFixed(1)}`}. Latest: through 17 Oct 2026.`;\n  }\n}",
 "    document.getElementById('pmNote').textContent=`Monthly mean surface PM₂.₅ (RH 35 %) from the NASA GEOS-CF v2 analysis on a 2° grid${abs?'':'; anomaly = this month minus the 2021–2025 same-month mean from GEOS-CF v1 (a version offset of roughly −0.8 µg/m³ is included)'}. Global mean ${c.mean.toFixed(1)} µg/m³${abs?'':`, mean anomaly ${c.manom>=0?'+':''}${c.manom.toFixed(1)}`}. Latest: through 17 Oct 2026.`;\n  } else if(baseMode==='co'){\n    const i=+coSl.value,c=CO.months[i],abs=coMode==='abs';baseLayer=layerFor('co',i).addTo(map);\n    const [y,m]=c.date.split('-');document.getElementById('coDate').textContent=MON[+m-1]+' '+y+(c.partial?' (partial)':'');\n    document.getElementById('coBar').style.background=`linear-gradient(90deg,${(abs?COSEQ:DIV).map(c=>`rgb(${c.join(',')})`).join(',')})`;\n    document.getElementById('coLab').innerHTML=abs?'<span>60 ppb</span><span>130</span><span>≥ 200 ppb</span>':'<span>−30 ppb</span><span>0</span><span>+30 ppb</span>';\n    document.getElementById('coNote').textContent=`AIRS (Aqua) Level-3 carbon monoxide volume mixing ratio at 500 hPa, daytime, monthly mean on a 1.5° grid${abs?'':'; anomaly = this month minus the 2021–2025 same-month mean'}. Mid-tropospheric CO is the cleanest satellite tracer of biomass-burning plumes. Source: NASA GIBS (AIRS L3 CO monthly; Sep–Oct 2026 are means of alternate daily images). Global mean ${c.mean.toFixed(0)} ppb${abs?'':`, mean anomaly ${c.manom>=0?'+':''}${c.manom.toFixed(1)} ppb`}.`;\n  } else if(baseMode==='firem'){\n    const i=+fmSl.value,c=FIREM.months[i],abs=fmMode==='abs';baseLayer=layerFor('firem',i).addTo(map);\n    const [y,m]=c.date.split('-');document.getElementById('fmDate').textContent=MON[+m-1]+' '+y+(c.partial?' (to 17 Oct)':'');\n    document.getElementById('fmBar').style.background=`linear-gradient(90deg,${(abs?FMSEQ:DIV).map(c=>`rgb(${c.join(',')})`).join(',')})`;\n    document.getElementById('fmLab').innerHTML=abs?'<span>1</span><span>~20</span><span>≥ 300 per cell</span>':'<span>−100</span><span>0</span><span>+100 per cell</span>';\n    document.getElementById('fmNote').textContent=`VIIRS (Suomi-NPP) active-fire detections per 1° cell, summed over every third day of the month and scaled ×3 to an approximate monthly count${abs?'':'; anomaly = this month minus the 2021–2025 same-month mean'}. Source: NASA GIBS VIIRS 375 m thermal-anomaly layer (rendered pixels counted, so dense fire clusters are undercounted). Global total ≈ ${c.total.toLocaleString()}${abs?'':`; mean anomaly ${c.manom>=0?'+':''}${c.manom.toFixed(1)} per cell`}.`;\n  }\n  if(document.getElementById('ckCmp').checked)showCmp();\n  updateHash();\n}"),
("['ocoSl','ndviSl','s3Sl','pmSl'].forEach(id=>document.getElementById(id).addEventListener('input',showBase));",
 "const slMode={ocoSl:'oco2',ndviSl:'ndvi',s3Sl:'s3',pmSl:'pm',coSl:'co',fmSl:'firem'};\nfor(const id in slMode) document.getElementById(id).addEventListener('input',()=>showBase(slMode[id]));\ndocument.querySelectorAll('#coMode button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#coMode button').forEach(x=>x.classList.toggle('on',x===b));coMode=b.dataset.m;showBase();}));\ndocument.querySelectorAll('#fmMode button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#fmMode button').forEach(x=>x.classList.toggle('on',x===b));fmMode=b.dataset.m;showBase();}));"),
# radio change: carry sync
("document.querySelectorAll('input[name=base]').forEach(r=>r.addEventListener('change',()=>{if(r.checked){baseMode=r.value;showBase();}}));",
 "document.querySelectorAll('input[name=base]').forEach(r=>r.addEventListener('change',()=>{if(r.checked){const prev=baseMode;baseMode=r.value;if(SL[prev])syncDates(prev);showBase();}}));"),
