# ---------- ENSO card, region tool, hash, keys (before about) ----------
("/* ---------- about ---------- */",
 "/* ---------- ENSO ---------- */\nconst NINO_M={};(function(){const acc={};for(const [d,s,a] of ENSO.weekly){const k=d.slice(0,7);(acc[k]=acc[k]||[]).push(a);}for(const k in acc)NINO_M[k]=+(acc[k].reduce((x,y)=>x+y,0)/acc[k].length).toFixed(2);})();\nfunction spark(cv,series,opts){const dpr=devicePixelRatio||1;const W=cv.clientWidth||300,H=cv.clientHeight||54;cv.width=W*dpr;cv.height=H*dpr;const g=cv.getContext('2d');g.scale(dpr,dpr);g.clearRect(0,0,W,H);const vals=series.map(p=>p[1]);const lo=opts.lo??Math.min(...vals),hi=opts.hi??Math.max(...vals);const x=i=>i/(series.length-1)*W,y=v=>H-4-(v-lo)/(hi-lo)*(H-8);\n  if(opts.zero!=null){const z=y(opts.zero);g.strokeStyle='#bbb';g.beginPath();g.moveTo(0,z);g.lineTo(W,z);g.stroke();}\n  if(opts.bands){for(const [a,b,c] of opts.bands){g.fillStyle=c;const y1=y(Math.min(b,hi)),y2=y(Math.max(a,lo));g.fillRect(0,y1,W,y2-y1);}}\n  g.beginPath();series.forEach((p,i)=>{i?g.lineTo(x(i),y(p[1])):g.moveTo(x(i),y(p[1]));});g.strokeStyle=opts.color;g.lineWidth=1.6;g.stroke();\n  if(opts.fillZero!=null){g.lineTo(x(series.length-1),y(opts.fillZero));g.lineTo(0,y(opts.fillZero));g.closePath();g.fillStyle=opts.fill;g.fill();}\n  g.fillStyle='#666';g.font='10px Open Sans';g.fillText(series[0][0].slice(0,4),2,H-1);g.textAlign='right';g.fillText(series[series.length-1][0].slice(0,7),W-2,H-1);}\nfunction renderEnso(){const L=ENSO.latest,ph=L.phase;const cls=ph==='El Niño'?'':ph==='La Niña'?'nina':'neu';\n  const gl=ENSO.global_co2;const gr=[];for(let i=12;i<gl.length;i++)gr.push([`${gl[i][0]}-${String(gl[i][1]).padStart(2,'0')}`,+(gl[i][3]-gl[i-12][3]).toFixed(2)]);\n  document.getElementById('ensoCard').innerHTML=`<div class=\"row1\"><span class=\"badge ${cls}\">${ph}</span><span class=\"v\">Niño 3.4 ${L.week[2]>0?'+':''}${L.week[2].toFixed(1)} °C</span><small>week of ${fmtD(L.week[0])} · ONI ${L.oni[0]} ${L.oni[1]}: ${L.oni[2]>0?'+':''}${L.oni[2].toFixed(2)}</small></div><small>Niño 3.4 weekly SST anomaly, 2014 → now (NOAA CPC, OISST v2.1, 1991–2020 base)</small><canvas id=\"ensoCv\"></canvas><small style=\"display:block;margin-top:6px\">Global CO₂ 12-month growth rate, ppm/yr (NOAA GML marine surface mean, deseasonalised); latest ${gr[gr.length-1][1].toFixed(2)}</small><canvas id=\"grCv\"></canvas>`;\n  spark(document.getElementById('ensoCv'),ENSO.weekly,{color:'#e8930b',fill:'rgba(232,147,11,.25)',fillZero:0,zero:0,lo:-3,hi:3.5,bands:[[0.5,9,'rgba(235,65,65,.07)'],[-9,-0.5,'rgba(44,133,215,.07)']]});\n  spark(document.getElementById('grCv'),gr,{color:'#2c85d7',fill:'rgba(44,133,215,.2)',fillZero:1,zero:2.5,lo:1,hi:4.5});}\nrenderEnso();addEventListener('resize',renderEnso);\n\n/* ---------- region comparison ---------- */\nlet regionOn=false,regionRect=null,regionBoxEl=null,regionStart=null;\nconst tRegion=document.getElementById('tRegion');\nfunction setRegion(on){regionOn=on;tRegion.classList.toggle('on',on);document.getElementById('map').style.cursor=on?'crosshair':'';if(on){map.dragging.disable();}else{map.dragging.enable();if(regionBoxEl){regionBoxEl.remove();regionBoxEl=null;}}}\ntRegion.addEventListener('click',()=>setRegion(!regionOn));\n(function(){const mapEl=document.getElementById('map');\n  mapEl.addEventListener('pointerdown',e=>{if(!regionOn||e.target.closest('.tools'))return;regionStart=map.mouseEventToLatLng(e);if(regionBoxEl)regionBoxEl.remove();regionBoxEl=document.createElement('div');regionBoxEl.className='regionBox';mapEl.appendChild(regionBoxEl);e.preventDefault();});\n  mapEl.addEventListener('pointermove',e=>{if(!regionOn||!regionStart||!regionBoxEl)return;const a=map.latLngToContainerPoint(regionStart),b=map.mouseEventToContainerPoint(e);regionBoxEl.style.left=Math.min(a.x,b.x)+'px';regionBoxEl.style.top=Math.min(a.y,b.y)+'px';regionBoxEl.style.width=Math.abs(a.x-b.x)+'px';regionBoxEl.style.height=Math.abs(a.y-b.y)+'px';});\n  window.addEventListener('pointerup',e=>{if(!regionOn||!regionStart)return;const end=map.mouseEventToLatLng(e);const b=L.latLngBounds(regionStart,end);regionStart=null;if(Math.abs(b.getNorth()-b.getSouth())<1||Math.abs(b.getEast()-b.getWest())<1)return;regionRect=b;showRegion(b);});})();\nfunction gridMean(arr,nx,ny,nodata,scale,bounds,latTop,latBot,lonL,lonR){const res=(latTop-latBot)/ny;const y0=Math.max(0,Math.floor((latTop-bounds.getNorth())/res)),y1=Math.min(ny-1,Math.floor((latTop-bounds.getSouth())/res));const x0=Math.max(0,Math.floor((bounds.getWest()-lonL)/res)),x1=Math.min(nx-1,Math.floor((bounds.getEast()-lonL)/res));let s=0,n=0;for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++){const v=arr[y*nx+x];if(v===nodata)continue;s+=v;n++;}return n?s/scale/n:null;}\nlet rcharts=[];\nfunction showRegion(b){const el=document.getElementById('chart');el.classList.add('open');document.body.classList.add('chartOpen');document.getElementById('cChart').style.display='none';document.querySelector('.stats').style.display='none';const g=document.getElementById('rgrid');g.style.display='';\n  document.getElementById('cTitle').textContent=`Region ${b.getSouth().toFixed(1)}° to ${b.getNorth().toFixed(1)}°, ${b.getWest().toFixed(1)}° to ${b.getEast().toFixed(1)}°`;document.getElementById('cMeta').textContent='Area means of each raster layer, with Niño 3.4 for reference. Draw another box or press the region button to exit.';\n  const series=[\n   {name:'MODIS NDVI anomaly',unit:'',dp:3,pts:NDVI2.months.map(c=>[c.date,gridMean(decode8(c.b64),NDVI2.nx,NDVI2.ny,-128,NDVI2.scale,b,90,-90,-180,180)]),color:'#01663c'},\n   {name:'OCO-2 XCO₂ (ppm)',unit:'ppm',dp:1,pts:OCO.cycles.map(c=>[c.end.slice(0,7),gridMean(decode16(c.b64),OCO.nx,OCO.ny,-32768,10,b,90,-90,-180,180)]),color:'#2c85d7'},\n   {name:'AIRS CO 500 hPa (ppb)',unit:'ppb',dp:0,pts:CO.months.map(c=>{const a=decodeU8(c.abs);const a16=new Int16Array(a.length);for(let k=0;k<a.length;k++)a16[k]=a[k]===0?-32768:a[k]*10;return [c.date,gridMean(a16,CO.nx,CO.ny,-32768,10,b,90,-90,-180,180)];}),color:'#8c1440'},\n   {name:'GEOS-CF PM₂.₅ (µg/m³)',unit:'µg/m³',dp:1,pts:PM.months.map(c=>[c.date,gridMean(decode16(c.abs),PM.nx,PM.ny,-32768,10,b,91,-91,-181,179)]),color:'#e8930b'},\n   {name:'VIIRS fire detections (per 1° cell, mean)',unit:'',dp:0,pts:FIREM.months.map(c=>[c.date,gridMean(decode16(c.abs),FIREM.nx,FIREM.ny,-32768,1,b,90,-90,-180,180)]),color:'#eb4141'},\n   {name:'Niño 3.4 SST anomaly (°C)',unit:'°C',dp:2,pts:Object.keys(NINO_M).filter(k=>k>='2025-09').sort().map(k=>[k,NINO_M[k]]),color:'#6b7fa3'}];\n  rcharts.forEach(c=>c.destroy());rcharts=[];g.innerHTML=series.map((s,i)=>`<div class=\"mini\"><span>${s.name}</span><canvas id=\"rc${i}\"></canvas></div>`).join('');\n  series.forEach((s,i)=>{rcharts.push(new Chart(document.getElementById('rc'+i),{type:'line',data:{labels:s.pts.map(p=>p[0]),datasets:[{data:s.pts.map(p=>p[1]),borderColor:s.color,backgroundColor:s.color+'22',borderWidth:1.6,pointRadius:2,tension:.25,fill:true,spanGaps:true}]},options:{responsive:true,maintainAspectRatio:false,animation:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>c.parsed.y==null?'–':c.parsed.y.toFixed(s.dp)+(s.unit?' '+s.unit:'')}}},scales:{x:{ticks:{font:{size:9},maxTicksLimit:6,color:'#6b7fa3'},grid:{display:false}},y:{ticks:{font:{size:9},color:'#6b7fa3',maxTicksLimit:4},grid:{color:'rgba(0,0,0,.06)'}}}}}));});\n  setTimeout(()=>{const c=map.getCenter(),z=map.getZoom();map.invalidateSize();map.setView(c,z,{animate:false});},30);}\n\n/* ---------- permalink ---------- */\nlet hashBusy=false;\nfunction updateHash(){if(hashBusy)return;const c=map.getCenter();const s=SL[baseMode];const parts=[`b=${baseMode}`,s?`i=${document.getElementById(s.el).value}`:'',`v=${c.lat.toFixed(2)},${c.lng.toFixed(2)},${map.getZoom()}`,`m=${anomMode}`,`s=${['ICOS','NOAA','OpenAQ'].map(n=>document.querySelector(`.netCk[data-net=${n}]`).checked?1:0).join('')}`,`g=${sel.ICOS},${sel.NOAA}`,`f=${document.getElementById('ckFire').checked?1:0}`,baseMode==='pm'?`pm=${pmMode}`:'',baseMode==='co'?`co=${coMode}`:'',baseMode==='firem'?`fm=${fmMode}`:''].filter(Boolean);history.replaceState(null,'','#'+parts.join('&'));}\nmap.on('moveend',updateHash);\nfunction readHash(){const h=location.hash.slice(1);if(!h)return;hashBusy=true;const q={};h.split('&').forEach(kv=>{const [k,v]=kv.split('=');q[k]=decodeURIComponent(v||'');});\n  if(q.b&&document.querySelector(`input[name=base][value=${q.b}]`)){baseMode=q.b;document.querySelector(`input[name=base][value=${q.b}]`).checked=true;}\n  if(q.pm)pmMode=q.pm;if(q.co)coMode=q.co;if(q.fm)fmMode=q.fm;\n  if(q.i!=null&&SL[baseMode]){const el=document.getElementById(SL[baseMode].el);el.value=Math.min(+el.max,Math.max(0,+q.i));syncDates(baseMode);}\n  if(q.m&&document.querySelector(`#anomMode button[data-m=${q.m}]`)){anomMode=q.m;document.querySelectorAll('#anomMode button').forEach(x=>x.classList.toggle('on',x.dataset.m===q.m));}\n  if(q.g){const [a,b]=q.g.split(',');if(VARS[a]){sel.ICOS=a;}if(VARS[b]){sel.NOAA=b;}document.querySelectorAll('input[name=varICOS]').forEach(r=>r.checked=r.value===sel.ICOS);document.querySelectorAll('input[name=varNOAA]').forEach(r=>r.checked=r.value===sel.NOAA);}\n  if(q.s){['ICOS','NOAA','OpenAQ'].forEach((n,i)=>{const ck=document.querySelector(`.netCk[data-net=${n}]`);const on=q.s[i]!=='0';if(ck.checked!==on){ck.checked=on;on?groups[n].addTo(map):map.removeLayer(groups[n]);}});}\n  if(q.f==='0'){document.getElementById('ckFire').checked=false;map.removeLayer(fireLayer);}\n  for(const net in NETS)buildNet(net);updateLegend();\n  ['pm','co','fm'].forEach(k=>{const id={pm:'pmMode',co:'coMode',fm:'fmMode'}[k];const mode={pm:pmMode,co:coMode,fm:fmMode}[k];document.querySelectorAll(`#${id} button`).forEach(x=>x.classList.toggle('on',x.dataset.m===mode));});\n  showBase();\n  if(q.v){const [la,lo,z]=q.v.split(',').map(Number);if(isFinite(la)&&isFinite(lo)&&isFinite(z))map.setView([la,lo],Math.max(map.getMinZoom(),z),{animate:false});}\n  hashBusy=false;updateHash();}\nreadHash();\n\n/* ---------- keyboard ---------- */\ndocument.addEventListener('keydown',e=>{if(e.target.tagName==='INPUT'||e.target.tagName==='TEXTAREA')return;const s=SL[baseMode];\n  if((e.key==='ArrowLeft'||e.key==='ArrowRight')&&s){const el=document.getElementById(s.el);el.value=Math.min(+el.max,Math.max(0,+el.value+(e.key==='ArrowRight'?1:-1)));showBase(baseMode);e.preventDefault();}\n  else if(e.key==='+'||e.key==='=')map.zoomIn();else if(e.key==='-'||e.key==='_')map.zoomOut();else if(e.key==='r'||e.key==='R')setRegion(!regionOn);\n  else if(e.key==='Escape'){setRegion(false);document.getElementById('chart').classList.remove('open');document.body.classList.remove('chartOpen');map.invalidateSize();}});\n\n/* ---------- about ---------- */"),
